/**
 * Loading indicator for work of unknown duration (`design/components/spinner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/spinner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Icon, claimSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/spinner.module.css'

export interface SpinnerProps {
  /**
   * Announced once, so screen reader users know something is loading.
   */
  label?: string
  size?: 'sm' | 'md' | 'lg'
}

/** Loading indicator for work of unknown duration. */
export default function Spinner(given: SpinnerProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', label: 'Loading' } as Defaults<SpinnerProps, 'size' | 'label'>,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <span class={styles.spinner} data-size={props.size} role="status" data-member="spinner">
        {/* glyph */}
        <span class={styles.glyph}>
          <Icon name="loading" size={props.size} />
        </span>
        {/* label */}
        <span class={styles.label}>{props.label}</span>
      </span>
    )
  })
}
